import UnifyAppsAnalyticsClient from './client';

export { useAnalytics, AnalyticsProvider } from './context';
export { UnifyAppsAnalyticsClient };
export * from './types';

export const createClient = (
  options: Parameters<UnifyAppsAnalyticsClient['setup']>[0]
) => {
  const client = new UnifyAppsAnalyticsClient();
  void client.setup(options);
  return client;
};
